import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"鎖箱子/門","description":"將自己的箱子上鎖，避免被其他玩家偷竊。","frontmatter":{"title":"鎖箱子/門","description":"將自己的箱子上鎖，避免被其他玩家偷竊。"},"headers":[],"relativePath":"feature/lock/index.md","filePath":"feature/lock.md"}'),r={name:"feature/lock/index.md"};function o(d,e,c,h,n,s){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="鎖箱子-門" tabindex="-1">鎖箱子/門 <a class="header-anchor" href="#鎖箱子-門" aria-label="Permalink to &quot;鎖箱子/門&quot;">​</a></h1><p>將箱子/門鎖定後，即可限制只有誰才能打開箱子/門(本伺服沒有領地)<br> 請玩家盡量將儲存私人物品的容器進行鎖定</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><p>對著箱子/門放告示牌即可鎖定完成<br><img src="https://i.imgur.com/blXVvlj.gif" style="width:70%;"></p><p>如果只是想放告示牌在箱子/門上，但不想鎖定箱子/門<br><b>請先蹲下 再放置告示牌</b></p><h2 id="可鎖定物件" tabindex="-1">可鎖定物件 <a class="header-anchor" href="#可鎖定物件" aria-label="Permalink to &quot;可鎖定物件&quot;">​</a></h2><ul><li>箱子類、熔爐類、發射器容器類、漏斗、釀造台 (界伏盒不能鎖)</li><li>門/柵欄門/地板門 也可以鎖定</li></ul><h2 id="增加使用人" tabindex="-1">增加使用人 <a class="header-anchor" href="#增加使用人" aria-label="Permalink to &quot;增加使用人&quot;">​</a></h2><h3 id="bl-行號-使用者的id" tabindex="-1"><code>/bl &lt;行號&gt; &lt;使用者的ID&gt;</code> <a class="header-anchor" href="#bl-行號-使用者的id" aria-label="Permalink to &quot;`/bl &lt;行號&gt; &lt;使用者的ID&gt;`&quot;">​</a></h3><ol><li>右鍵點擊告示牌</li><li>輸入<code>/bl &lt;行號&gt; &lt;使用者的ID&gt;</code>即可編輯<br> (告示牌有四行 從上往下數 2 3 4)<br><img src="https://i.imgur.com/syFk1U3.gif" style="width:70%;"></li></ol><h3 id="增加更多牌子" tabindex="-1">增加更多牌子 <a class="header-anchor" href="#增加更多牌子" aria-label="Permalink to &quot;增加更多牌子&quot;">​</a></h3><p>若ID不夠位置放可以在同個箱子/門上放第二個告示牌<br><img src="https://i.imgur.com/pnpsJPL.gif" style="width:70%;"><br> (圖片有點大 要等他跑一下)</p><h2 id="讓所有人都能使用" tabindex="-1">讓所有人都能使用 <a class="header-anchor" href="#讓所有人都能使用" aria-label="Permalink to &quot;讓所有人都能使用&quot;">​</a></h2><ul><li>可以讓箱子/門設定成每個人都能開跟拿東西<br> 但只有你能拆掉箱子/門</li><li>適合用在公共箱子/建築</li></ul><h3 id="增加標籤-所有人-或-everyone" tabindex="-1">增加標籤 <code>[所有人]或[Everyone]</code> <a class="header-anchor" href="#增加標籤-所有人-或-everyone" aria-label="Permalink to &quot;增加標籤 `[所有人]或[Everyone]`&quot;">​</a></h3><ul><li>輸入<code>/bl &lt;行號&gt; [所有人]</code><ul><li>EX : <code>/bl 3 [所有人]</code><br><img src="https://i.imgur.com/4KC5ZGX.png" style="width:50%;"></li></ul></li></ul><h2 id="定時關門-timer-時長" tabindex="-1">定時關門 <code>[Timer:時長]</code> <a class="header-anchor" href="#定時關門-timer-時長" aria-label="Permalink to &quot;定時關門 `[Timer:時長]`&quot;">​</a></h2><ul><li>輸入<code>/bl &lt;行號&gt; [Timer:時長]</code><ul><li>EX : <code>/bl 3 [Timer:1]</code></li></ul></li></ul><h2 id="允許用漏斗傳輸物品" tabindex="-1">允許用漏斗傳輸物品 <a class="header-anchor" href="#允許用漏斗傳輸物品" aria-label="Permalink to &quot;允許用漏斗傳輸物品&quot;">​</a></h2><ul><li>鎖定箱子後，物品依然能用漏斗/漏斗礦車流進箱子裡</li><li>希望你鎖定的容器可以利用漏斗『流出物品』</li><li>此設定只有主伺服才需要(設施服/資源服不用設定)</li></ul><h3 id="增加標籤-紅石" tabindex="-1">增加標籤 <code>[紅石]</code> <a class="header-anchor" href="#增加標籤-紅石" aria-label="Permalink to &quot;增加標籤 `[紅石]`&quot;">​</a></h3><ul><li>輸入<code>/bl &lt;行號&gt; [紅石]</code><ul><li>EX : <code>/bl 3 [紅石]</code><br><img src="https://i.imgur.com/D9SQNYQ.png" style="width:50%;"></li></ul></li></ul><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ul><li>現在並不支援顏色字設定</li><li>早期的鎖箱牌子上的特殊顏色會因為使用而消失，這是正常的</li></ul>',24)])])}const m=a(r,[["render",o]]);export{b as __pageData,m as default};
